<?php use Hls\Http\View as V; use Hls\Http\Icons; ?>
<div class="dashboard" data-dashboard-role="<?= V::escape($dashboard['role']) ?>">
<div class="dashboard-context"><p><?= V::escape($dashboard['definition']['focus']) ?></p></div>
<?= $this->component('dashboard-filters',['dashboard'=>$dashboard]) ?>
<?php if ($dashboard['owner'] && $dashboard['operational']): $o=$dashboard['operational']; ?>
<?php $kpiGroups=[['TRUCKING',[['Total Delivery Note',$o['dn']['total'],'/trucking/dns'],['Dalam Proses',$o['dn']['active'],'/trucking/dns?status=active'],['Pengiriman Selesai',$o['dn']['completed'],'/trucking/dns?status=completed'],['Manifest Aktif',$o['manifests']['total'],'/trucking/manifests'],['Klaim Terbuka',$o['claims']['open'],'/trucking/claims?status=open']]],['EQUIPMENT',[['Total Unit',$o['units']['total'],'/equipment/contracts'],['Unit Tersedia',$o['units']['available'],'/equipment/contracts'],['Unit Digunakan',$o['units']['in_use'],'/equipment/contracts?status=ACTIVE'],['Kontrak Aktif',$o['contracts']['total'],'/equipment/contracts?status=ACTIVE'],['Timesheet Menunggu',$o['timesheets']['total'],'/equipment/verification']]]]; foreach($kpiGroups as [$group,$cards]): ?><section class="executive-kpi-section" aria-labelledby="kpi-<?= strtolower($group) ?>"><h2 id="kpi-<?= strtolower($group) ?>"><?= $group ?></h2><div class="executive-kpis"><?php foreach($cards as [$label,$value,$route]): ?><article class="panel kpi-card executive-kpi"><div class="kpi-label"><h3><?= V::escape($label) ?></h3></div><strong class="kpi-value"><?= (int)$value ?></strong><p><a href="<?= V::escape($this->url($route)) ?>">Lihat detail</a></p></article><?php endforeach ?></div></section><?php endforeach ?>
<section class="panel finance-unavailable"><h2>Keuangan</h2><p class="field-hint">Indikator omzet, piutang, utang, kas/bank, pengeluaran, dan laba/rugi belum tersedia karena modul Finance belum diimplementasikan.</p></section>
<?php endif ?>
<?php if ($dashboard['metrics']): ?><section class="kpi-grid" aria-label="Ringkasan administrasi"><?php foreach ($dashboard['metrics'] as $metric): ?><?= $this->component('dashboard-kpi',compact('metric')) ?><?php endforeach ?></section><?php endif ?>
<?php if ($dashboard['pending']): ?><div class="dashboard-grid"><?php foreach ($dashboard['pending'] as $section): ?><?= $this->component('dashboard-pending',compact('section')) ?><?php endforeach ?></div><?php endif ?>
<?php if ($dashboard['metrics']): ?>
<?php ob_start(); if ($dashboard['attention']): ?><ul class="attention-list"><?php foreach ($dashboard['attention'] as $attention): ?><li><a href="<?= V::escape($this->url($attention['route'])) ?>"><?= V::escape($attention['label']) ?></a><span class="status-badge"><?= (int)$attention['count'] ?></span></li><?php endforeach ?></ul><?php else: ?><?= $this->component('empty-state',['heading'=>'Tidak ada tindak lanjut administrasi','message'=>'Tidak ditemukan catatan pada pemeriksaan yang diizinkan dalam cakupan terpilih.']) ?><?php endif; echo $this->component('card',['heading'=>'Perlu perhatian','body'=>ob_get_clean()]); ?>
<?php endif ?>
<?php if ($dashboard['roleUsers']!==null): ob_start(); foreach ($dashboard['roleUsers'] as $row): ?><tr><td><?= V::escape($row['name']) ?></td><td><?= (int)$row['active'] ?></td></tr><?php endforeach; echo $this->component('table',['caption'=>'Pengguna aktif per role · cakupan cabang terpilih','headers'=>['Role','Pengguna aktif'],'rowsHtml'=>ob_get_clean(),'hasRows'=>(bool)$dashboard['roleUsers']]); endif ?>
<?php if ($dashboard['canAudit']): ?>
<?php if ($dashboard['audit']!==null): ob_start(); foreach ($dashboard['audit'] as $event): ?><tr data-audit-id="<?= (int)$event['id'] ?>"><td><?= V::escape($event['created_at']) ?></td><td><?= V::escape($event['actor']??'Anonim') ?></td><td><?= V::escape($event['action']) ?></td><td><?= V::escape($event['entity'].' #'.($event['entity_id']??'')) ?></td></tr><?php endforeach; echo $this->component('table',['caption'=>'Aktivitas audit terbaru · '. $dashboard['start'].' s.d. '.$dashboard['end'].' WITA','headers'=>['Waktu WITA','Aktor','Aksi','Entitas'],'rowsHtml'=>ob_get_clean(),'hasRows'=>(bool)$dashboard['audit'],'emptyHeading'=>'Tidak ada aktivitas pada periode ini','emptyMessage'=>'Tidak ditemukan catatan audit dalam rentang tanggal yang dipilih.']); ?>
<?php else: ?><?= $this->component('card',['heading'=>'Aktivitas audit per cabang','body'=>'<p class="field-hint">Belum tersedia. Pilih seluruh cabang untuk melihat audit global sesuai periode. Catatan audit belum memiliki cakupan cabang transaksi yang dapat dipastikan.</p>']) ?><?php endif ?>
<?php endif ?>
<?php ob_start(); if ($dashboard['branches']): ?><ul class="branch-list"><?php foreach ($dashboard['branches'] as $branch): ?><li><?= V::escape($branch['code'].' — '.$branch['name']) ?> <span class="status-badge <?= $branch['active'] ? '' : 'inactive' ?>"><?= $branch['active'] ? 'Aktif' : 'Nonaktif' ?></span></li><?php endforeach ?></ul><?php else: ?><?= $this->component('empty-state',['heading'=>'Belum ada cabang','message'=>'Belum ada cabang dalam cakupan akun ini.']) ?><?php endif; echo $this->component('card',['heading'=>'Cabang dalam akses Anda','body'=>ob_get_clean()]); ?>
<?php ob_start(); ?><dl class="account-list"><div><dt>Nama</dt><dd><?= V::escape($access->user['name']) ?></dd></div><div><dt>Email</dt><dd><?= V::escape($access->user['email']) ?></dd></div><div><dt>Role</dt><dd><?= V::escape($access->user['role_name']) ?></dd></div><div><dt>Cakupan</dt><dd><?= $access->user['all_branches'] ? 'Seluruh cabang' : 'Cabang yang ditetapkan' ?></dd></div></dl><?php echo $this->component('card',['heading'=>'Identitas akun','id'=>'account-details','body'=>ob_get_clean()]); ?>
</div>
